"""
ReAct (Reasoning + Acting) agent implementation.
The agent interleaves Thought, Action, and Observation steps.
"""
import openai, json, re, math

# ---------- Tool registry ----------
TOOLS = {}

def tool(name: str, description: str):
    """Decorator to register a tool the agent can call."""
    def decorator(func):
        TOOLS[name] = {"fn": func, "description": description}
        return func
    return decorator

@tool("calculator", "Evaluate a math expression. Input: a Python math expression string.")
def calculator(expression: str) -> str:
    """Safely evaluate arithmetic expressions."""
    allowed = set("0123456789+-*/(). ")
    if not all(ch in allowed for ch in expression):
        return f"Error: expression contains disallowed characters."
    try:
        result = eval(expression, {"__builtins__": {}}, {"math": math})
        return str(result)
    except Exception as e:
        return f"Error: {e}"

@tool("lookup", "Look up a fact. Input: a short search query string.")
def lookup(query: str) -> str:
    """Simulated knowledge lookup (replace with real API)."""
    knowledge = {
        "speed of light": "299,792,458 meters per second",
        "population of france": "approximately 68 million (2024)",
        "boiling point of water": "100 degrees Celsius at 1 atm",
    }
    query_lower = query.lower()
    for key, value in knowledge.items():
        if key in query_lower:
            return value
    return f"No results found for: {query}"


class ReActAgent:
    """
    ReAct agent that reasons and acts in an interleaved loop.
    Follows the pattern: Thought -> Action -> Observation -> Thought -> ...
    """
    SYSTEM_PROMPT = """You are a helpful assistant that solves problems by
reasoning step-by-step and using tools when needed.

Available tools:
{tool_descriptions}

On each turn you MUST output exactly ONE of these formats:

Thought: <your reasoning about the current state>
Action: <tool_name>(<input>)

OR, when you have the final answer:

Thought: <your final reasoning>
Answer: <your final answer>

IMPORTANT: Output ONLY one Thought + Action pair, or one Thought + Answer.
Do not output multiple steps at once."""

    def __init__(self, client, model="gpt-4", max_steps=8, verbose=True):
        self.client = client
        self.model = model
        self.max_steps = max_steps
        self.verbose = verbose

    def _build_system(self) -> str:
        descs = "\n".join(
            f"- {name}: {info['description']}" for name, info in TOOLS.items()
        )
        return self.SYSTEM_PROMPT.format(tool_descriptions=descs)

    def _parse_action(self, text: str):
        """Extract tool name and argument from Action: tool(arg)."""
        match = re.search(r"Action:\s*(\w+)\((.+?)\)\s*$", text, re.M | re.S)
        if match:
            return match.group(1), match.group(2).strip().strip("\"'")
        return None, None

    def run(self, question: str) -> str:
        messages = [
            {"role": "system", "content": self._build_system()},
            {"role": "user", "content": question},
        ]

        for step in range(self.max_steps):
            resp = self.client.chat.completions.create(
                model=self.model,
                messages=messages,
                temperature=0.1,
            )
            reply = resp.choices[0].message.content
            messages.append({"role": "assistant", "content": reply})

            if self.verbose:
                print(f"\n--- Step {step + 1} ---\n{reply}")

            # Check if the agent produced a final answer
            if "Answer:" in reply:
                answer = reply.split("Answer:")[-1].strip()
                return answer

            # Parse and execute the action
            tool_name, tool_input = self._parse_action(reply)
            if tool_name and tool_name in TOOLS:
                observation = TOOLS[tool_name]["fn"](tool_input)
            elif tool_name:
                observation = f"Error: unknown tool '{tool_name}'"
            else:
                observation = "Error: could not parse your action. Use Action: tool(input)"

            obs_msg = f"Observation: {observation}"
            messages.append({"role": "user", "content": obs_msg})
            if self.verbose:
                print(obs_msg)

        return "Max steps reached without a final answer."


# Example usage
if __name__ == "__main__":
    client = openai.OpenAI()
    agent = ReActAgent(client, max_steps=6)
    answer = agent.run(
        "How long does it take light to travel from the Sun to Earth, "
        "given the Sun is about 149.6 million km away?"
    )
    print(f"\nFinal answer: {answer}")

"""
Tool-use via the OpenAI function-calling API.
Demonstrates how to define tool schemas, let the model decide
which tool to call, execute it, and feed results back.
"""
import openai, json

# ---------- Define tools as JSON Schema ----------
TOOL_SCHEMAS = [
    {
        "type": "function",
        "function": {
            "name": "get_weather",
            "description": "Get current weather for a given city.",
            "parameters": {
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "City name, e.g. 'Berlin'"
                    },
                    "units": {
                        "type": "string",
                        "enum": ["celsius", "fahrenheit"],
                        "description": "Temperature unit"
                    }
                },
                "required": ["city"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "search_database",
            "description": "Search a product database by query and optional filters.",
            "parameters": {
                "type": "object",
                "properties": {
                    "query": {"type": "string", "description": "Search terms"},
                    "category": {"type": "string", "description": "Product category"},
                    "max_price": {"type": "number", "description": "Maximum price"}
                },
                "required": ["query"]
            }
        }
    },
    {
        "type": "function",
        "function": {
            "name": "send_email",
            "description": "Send an email to a recipient.",
            "parameters": {
                "type": "object",
                "properties": {
                    "to": {"type": "string", "description": "Recipient email"},
                    "subject": {"type": "string"},
                    "body": {"type": "string"}
                },
                "required": ["to", "subject", "body"]
            }
        }
    }
]


# ---------- Tool implementations ----------
def get_weather(city: str, units: str = "celsius") -> dict:
    """Simulated weather API call."""
    # In production, call a real weather API here
    return {"city": city, "temp": 22, "units": units, "condition": "partly cloudy"}

def search_database(query: str, category: str = None, max_price: float = None) -> list:
    """Simulated database search."""
    results = [
        {"name": f"{query} Pro", "price": 49.99, "category": category or "general"},
        {"name": f"{query} Basic", "price": 19.99, "category": category or "general"},
    ]
    if max_price:
        results = [r for r in results if r["price"] <= max_price]
    return results

def send_email(to: str, subject: str, body: str) -> dict:
    """Simulated email sending."""
    print(f"[EMAIL] To: {to} | Subject: {subject}")
    return {"status": "sent", "message_id": "msg_abc123"}


TOOL_FUNCTIONS = {
    "get_weather": get_weather,
    "search_database": search_database,
    "send_email": send_email,
}


def run_function_calling_loop(client, user_message: str, model="gpt-4"):
    """
    Complete function-calling loop:
    1. Send user message with tool schemas
    2. If model returns tool_calls, execute them
    3. Feed results back, let model produce final response
    """
    messages = [
        {"role": "system", "content": "You are a helpful assistant. Use the provided tools when needed."},
        {"role": "user", "content": user_message},
    ]

    while True:
        response = client.chat.completions.create(
            model=model,
            messages=messages,
            tools=TOOL_SCHEMAS,
            tool_choice="auto",
        )
        msg = response.choices[0].message

        # If no tool calls, we have the final text response
        if not msg.tool_calls:
            print(f"Assistant: {msg.content}")
            return msg.content

        # Process each tool call
        messages.append(msg)  # add assistant message with tool_calls
        for tool_call in msg.tool_calls:
            fn_name = tool_call.function.name
            fn_args = json.loads(tool_call.function.arguments)
            print(f"  Calling {fn_name}({fn_args})")

            # Execute the tool
            if fn_name in TOOL_FUNCTIONS:
                result = TOOL_FUNCTIONS[fn_name](**fn_args)
            else:
                result = {"error": f"Unknown function: {fn_name}"}

            # Append the tool result
            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps(result),
            })


# Example usage
if __name__ == "__main__":
    client = openai.OpenAI()
    run_function_calling_loop(
        client,
        "What is the weather in Berlin? Also search for 'wireless headphones' under 30 euros."
    )
